3	import React, { useEffect, useRef, useState, useCallback } from 'react';
4	import { Terminal as LucideTerminal, X, Play, RefreshCw, AlertCircle } from 'lucide-react';
5	import type { Terminal as XTermTerminal } from '@xterm/xterm';
6	import type { FitAddon as XTermFitAddon } from '@xterm/addon-fit';
7	import type { WebLinksAddon as XTermWebLinksAddon } from '@xterm/addon-web-links';
8	import '@xterm/xterm/css/xterm.css';
9	import { useFabricManagement } from '@/hooks/use-fabric-management';
10	import { Button } from '@/components/ui/button';
11	import { API_BASE_URL, getAuthHeaders } from '@/lib/api';
12	
13	interface ConsolePanelProps {
14	  isOpen: boolean;
15	  onClose: () => void;
16	  nodeId?: string;
17	  fabricId?: string;
18	  isMonitorOpen?: boolean;
19	}
20	
21	const ConsolePanel: React.FC<ConsolePanelProps> = ({ isOpen, onClose, nodeId, fabricId, isMonitorOpen }) => {
22	  const terminalRef = useRef<HTMLDivElement>(null);
23	  const xtermRef = useRef<XTermTerminal | null>(null);
24	  const fitAddonRef = useRef<XTermFitAddon | null>(null);
25	  const wsRef = useRef<WebSocket | null>(null);
26	  const sessionIdRef = useRef<string | null>(null);
27	  const pollIntervalRef = useRef<NodeJS.Timeout | null>(null);
28	  const inputBufferRef = useRef<string>('');
29	  const [isInitializing, setIsInitializing] = useState(false);
30	  const [sshConnected, setSshConnected] = useState(false);
31	  const [connectionMode, setConnectionMode] = useState<'knirvshell' | 'knirvagent' | 'ssh' | 'local'>('local');
32	  const connectionModeRef = useRef<'knirvshell' | 'knirvagent' | 'ssh' | 'local'>('local');
33	
34	  const updateConnectionModeRef = (mode: 'knirvshell' | 'knirvagent' | 'ssh' | 'local') => {
35	    connectionModeRef.current = mode;
36	    setConnectionMode(mode);
37	  };
38	
39	  const { fetchFabricLogs } = useFabricManagement();
40	
41	  // Create a KNIRVCLI session and set up polling for output
42	  const connectKNIRVCLI = useCallback(async (term: XTermTerminal) => {
43	    if (!nodeId) return false;
44	    try {
45	      const resp = await fetch(`${API_BASE_URL}/api/v1/shell/sessions`, {
46	        method: 'POST',
47	        headers: getAuthHeaders(),
48	        body: JSON.stringify({ 
49	          command: 'terminal:start',
50	          node_id: nodeId,
51	          streaming: true 
52	        }),
53	      });
54	      if (!resp.ok) return false;
55	      const data = await resp.json();
56	      sessionIdRef.current = data.session_id;
57	      updateConnectionModeRef('knirvshell');
58	
59	      // Quick initial poll — if the session already closed (command failed
60	      // immediately), don't claim the connection; let the fallback chain
61	      // (KNIRVAGENT → SSH → local shell) try instead.
62	      const initResp = await fetch(
63	        `${API_BASE_URL}/api/v1/shell/sessions/${sessionIdRef.current}`,
64	        { headers: getAuthHeaders() }
65	      );
66	      if (initResp.ok) {
67	        const initSess = await initResp.json();
68	        if (initSess.closed) {
69	          sessionIdRef.current = null;
70	          return false;
71	        }
72	      }
73	      
74	      term.writeln('\x1b[32m[CONNECTED] KNIRVCLI session established.\x1b[0m');
75	      term.write('\x1b[1;32m$ \x1b[0m');
76	
77	      // Poll for session output
78	      let lastOutputLen = 0;
79	      const pollOutput = async () => {
80	        if (!sessionIdRef.current) return;
81	        try {
82	          const outputResp = await fetch(
83	            `${API_BASE_URL}/api/v1/shell/sessions/${sessionIdRef.current}`,
84	            { headers: getAuthHeaders() }
85	          );
86	          if (outputResp.ok) {
87	            const session = await outputResp.json();
88	            if (session.output && Array.isArray(session.output)) {
89	              // Only write new chunks since last poll
90	              const newChunks = session.output.slice(lastOutputLen);
91	              if (newChunks.length > 0) {
92	                term.write(newChunks.join(''));
93	                lastOutputLen = session.output.length;
94	              }
95	            }
96	            if (session.closed) {
97	              term.writeln('\x1b[33m[DISCONNECTED] Session closed.\x1b[0m');
98	              setSshConnected(false);
99	              if (pollIntervalRef.current) {
100	                clearInterval(pollIntervalRef.current);
101	              }
102	            }
103	          }
104	        } catch { /* ignore polling errors */ }
105	      };
106	
107	      pollIntervalRef.current = setInterval(pollOutput, 100);
108	      setSshConnected(true);
109	      return true;
110	    } catch {
111	      return false;
112	    }
113	  }, [nodeId]);
114	
115	  // Send input to KNIRVCLI session
116	  const sendToKNIRVCLI = useCallback(async (input: string) => {
117	    if (!sessionIdRef.current) return;
118	    try {
119	      await fetch(`${API_BASE_URL}/api/v1/shell/sessions/${sessionIdRef.current}/input`, {
120	        method: 'POST',
121	        headers: getAuthHeaders(),
122	        body: JSON.stringify({ input }),
123	      });
124	    } catch { /* ignore send errors */ }
125	  }, []);
126	
127	  // Attempt to connect the terminal to the backend SSH WebSocket for the given node.
128	  const connectSSH = useCallback(async (term: XTermTerminal) => {
129	    if (!nodeId) return false;
130	    try {
131	      const resp = await fetch(`${API_BASE_URL}/api/dve/${nodeId}/ssh-session`, {
132	        method: 'POST',
133	        headers: getAuthHeaders(),
134	        body: JSON.stringify({ username: 'dve-admin' }),
135	      });
136	      if (!resp.ok) return false;
137	      const data = await resp.json();
138	      const wsProto = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
139	      const wsHost = window.location.host;
140	      const ws = new WebSocket(`${wsProto}//${wsHost}${data.ws_url}`);
141	      wsRef.current = ws;
142	      updateConnectionModeRef('ssh');
