13	// FlexibleStringSlice is a []string that also accepts JSON numbers,
14	// so allow_from can contain both "123" and 123.
15	type FlexibleStringSlice []string
16	
17	func (f *FlexibleStringSlice) UnmarshalJSON(data []byte) error {
18		// Try []string first
19		var ss []string
20		if err := json.Unmarshal(data, &ss); err == nil {
21			*f = ss
22			return nil
23		}
24	
25		// Try []interface{} to handle mixed types
26		var raw []interface{}
27		if err := json.Unmarshal(data, &raw); err != nil {
28			return err
29		}
30	
31		result := make([]string, 0, len(raw))
32		for _, v := range raw {
33			switch val := v.(type) {
34			case string:
35				result = append(result, val)
36			case float64:
37				result = append(result, fmt.Sprintf("%.0f", val))
38			default:
39				result = append(result, fmt.Sprintf("%v", val))
40			}
41		}
42		*f = result
43		return nil
44	}
