312	func LoadConfig(path string) (*Config, error) {
313		cfg := DefaultConfig()
314	
315		data, err := os.ReadFile(path)
316		if err != nil {
317			if os.IsNotExist(err) {
318				return cfg, nil
319			}
320			return nil, err
321		}
322	
323		if err := json.Unmarshal(data, cfg); err != nil {
324			return nil, err
325		}
326	
327		if err := env.Parse(cfg); err != nil {
328			return nil, err
329		}
330	
331		// Fallback: accept simple env var names (e.g. GEMINI_API_KEY instead of
332		// KNIRV_PROVIDERS_GEMINI_API_KEY) for backward compatibility with
333		// the KNIRVSERVER root.key injection system.
334		simpleKeyFallbacks := map[string]func(*Config) *string{
335			"ANTHROPIC_API_KEY": func(c *Config) *string { return &c.Providers.Anthropic.APIKey },
336			"DEEPSEEK_API_KEY":  func(c *Config) *string { return &c.Providers.DeepSeek.APIKey },
337			"GEMINI_API_KEY":    func(c *Config) *string { return &c.Providers.Gemini.APIKey },
338			"OPENAI_API_KEY":    func(c *Config) *string { return &c.Providers.OpenAI.APIKey },
339			"CEREBRAS_API_KEY":  func(c *Config) *string { return &c.Providers.ShengSuanYun.APIKey },
340		}
341		for envName, setter := range simpleKeyFallbacks {
342			if val, ok := os.LookupEnv(envName); ok && val != "" {
343				ptr := setter(cfg)
344				if *ptr == "" {
345					*ptr = val
346				}
347			}
348		}
349	
350		return cfg, nil
351	}
352	
353	func SaveConfig(path string, cfg *Config) error {
354		cfg.mu.RLock()
355		defer cfg.mu.RUnlock()
356	
357		data, err := json.MarshalIndent(cfg, "", "  ")
358		if err != nil {
359			return err
360		}
361	
362		dir := filepath.Dir(path)
363		if err := os.MkdirAll(dir, 0755); err != nil {
364			return err
365		}
366	
367		return os.WriteFile(path, data, 0644)
368	}
