376	func (c *Config) GetAPIKey() string {
377		c.mu.RLock()
378		defer c.mu.RUnlock()
379		if c.Providers.OpenRouter.APIKey != "" {
380			return c.Providers.OpenRouter.APIKey
381		}
382		if c.Providers.Anthropic.APIKey != "" {
383			return c.Providers.Anthropic.APIKey
384		}
385		if c.Providers.OpenAI.APIKey != "" {
386			return c.Providers.OpenAI.APIKey
387		}
388		if c.Providers.Gemini.APIKey != "" {
389			return c.Providers.Gemini.APIKey
390		}
391		if c.Providers.Groq.APIKey != "" {
392			return c.Providers.Groq.APIKey
393		}
394		if c.Providers.VLLM.APIKey != "" {
395			return c.Providers.VLLM.APIKey
396		}
397		if c.Providers.ShengSuanYun.APIKey != "" {
398			return c.Providers.ShengSuanYun.APIKey
399		}
400		return ""
401	}
402	
403	func (c *Config) GetAPIBase() string {
404		c.mu.RLock()
405		defer c.mu.RUnlock()
406		if c.Providers.OpenRouter.APIKey != "" {
407			if c.Providers.OpenRouter.APIBase != "" {
408				return c.Providers.OpenRouter.APIBase
409			}
410			return "https://openrouter.ai/api/v1"
411		}
412		if c.Providers.VLLM.APIKey != "" && c.Providers.VLLM.APIBase != "" {
413			return c.Providers.VLLM.APIBase
